CREATE DATABASE IF NOT EXISTS community_library CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE community_library;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,phone VARCHAR(40),password VARCHAR(255) NOT NULL,role ENUM('admin','student') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS books(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,author VARCHAR(160) NOT NULL,isbn VARCHAR(40),category VARCHAR(100),quantity INT NOT NULL DEFAULT 1,available INT NOT NULL DEFAULT 1,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS loans(id INT AUTO_INCREMENT PRIMARY KEY,book_id INT NOT NULL,user_id INT NOT NULL,issued_by INT NOT NULL,issued_at DATETIME DEFAULT CURRENT_TIMESTAMP,due_date DATE NOT NULL,returned_at DATETIME NULL,status ENUM('issued','returned') DEFAULT 'issued',FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(issued_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100),details VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
